'use strict';

/**
 * /v1/operators — list available Mobile Money operators and countries.
 */
class Operators {
  constructor(client) {
    this.client = client;
  }

  /**
   * List all available operators.
   */
  list() {
    return this.client.request('GET', '/v1/operators');
  }

  /**
   * List supported countries.
   */
  countries() {
    return this.client.request('GET', '/v1/operators/countries');
  }

  /**
   * Retrieve a single operator by code (e.g. "ORANGE_MONEY_CI").
   * @param {string} code
   */
  retrieve(code) {
    return this.client.request('GET', `/v1/operators/${encodeURIComponent(code)}`);
  }
}

module.exports = Operators;
